lineas.c:
logi=> select zona_destino, estado, count(*) from bultos
where zona_destino in ('Norte','Sur') and estado in ('devuelto','perdido')
group by rollup (zona_destino, estado) order by zona_destino, estado;

logi=> select zona_destino, estado, count(*), grouping(zona_destino, estado) as g from bultos
where zona_destino in ('Norte','Sur') and estado in ('devuelto','perdido')
group by rollup (zona_destino, estado) order by g, zona_destino, estado;

logi=> select d.nombre, count(*) as con_star, count(b.id) as bultos
from depositos d left join bultos b on b.deposito_id = d.id
group by d.nombre order by d.nombre;

logi=> select z.zona, z.kg, i.intentos
from (select zona_destino as zona, round(sum(peso_kg)) as kg from bultos group by zona_destino) z
join (select b.zona_destino as zona, count(*) as intentos
      from bultos b join intentos i on i.bulto_id = b.id group by b.zona_destino) i using (zona)
order by zona;
